package sessionresult

import (
	"math"
	"sort"
)

// pow10 is JavaScript's 10 ** y for an exponent the awards can reach. The engine's math library decides the last bit of a power, and
// neither Go's math.Pow nor a correctly rounded power always gives the same bit: two of the 1115 reachable exponents change an
// expected win chance, so the values the TypeScript produced are the table (pow10_table_gen.go, generated by
// testdata/tools/gen-pow10-table.mjs). An exponent outside it (not reachable: teams have one to five players with level indexes 0
// to 8) falls back to math.Pow.
func pow10(y float64) float64 {
	if p, ok := lookupPow10(y); ok {
		return p
	}
	return math.Pow(10, y)
}

func lookupPow10(y float64) (float64, bool) {
	bits := math.Float64bits(y)
	i := sort.Search(len(pow10Table), func(i int) bool { return pow10Table[i].y >= bits })
	if i < len(pow10Table) && pow10Table[i].y == bits {
		return math.Float64frombits(pow10Table[i].pow), true
	}
	return 0, false
}
